import React, { useEffect, useState, useRef } from "react";



import { getStore, updStore, gen16CodeId, fetchEncryptStream, ObjectKeys, genNumId, parseFloatToDecimal, qryStore, generateComprobanteId, Log, Log$$, parseDateMMDDYYYY } from "../../../stores/Utils";

import {   SvgIcon_Cmpt, TextInput_Cmpt } from "../../../components";


import "./styles.css"
import { CloseModal } from "../../../components/DialogHRM";
import { PickCustomer_Cmpt } from "../../ComprobanteParametrizados";
import { useNavigate } from "react-router";
import { get_balances_by_type } from "../../CuentasContables/services/server_fetching";
import { GrayButton } from "../../../components/Buttons";

const Svg = SvgIcon_Cmpt();

const TextInput = TextInput_Cmpt();

const DropInput = PickCustomer_Cmpt();


const frmNm = "new_multi_deposit_prov";
const multi_deposit_by_doc = "multi_deposit_by_prov_Doc";

const DepositManual  = ({ data, confirm }) => {
	const initialize = useRef(false);
	const [, set_obs] = useState(0);
	const navigate = useNavigate();

	useEffect(() => {
		if (!initialize.current) {
			initialize.current = true;
			get_balances_by_type("global_accounts","global_account_params",cb_result);
			updStore("PamentMethodAccount", null);
			
			updStore(multi_deposit_by_doc, null);
			updStore("accountPicker", {});
			set_obs(gen16CodeId())
		}
	});

	const cb_result = () => {
		set_obs(gen16CodeId())
	};
	

const saveMulti  = async ()  => {
	let ffm = getStore(frmNm) || {};

	let comp2save = [];
	ffm["date"] = ffm["depositDate"];

	
	if(!ffm["date"]){
		ffm["date"] = (new Date()).getTime()+4800;
	}
	
	let comprobanteId = await generateComprobanteId(ffm["date"]);





	let bankGlobal = getStore("global_account_params")?.cash_bank;
	
	let nnfrm = {};
	nnfrm["document"] =  getStore(frmNm)?.id;
	nnfrm["account"] = bankGlobal?.account;
	nnfrm["subAccount"] = bankGlobal?.subAccount;
	nnfrm["type"] ="debit";
	nnfrm["amount"] = getStore(frmNm)?.amount*1;
	nnfrm["operationId"] = gen16CodeId();
	comp2save.push(nnfrm)


	/*
	let commisiAcc = getStore("global_account_params")?.bankComisions;
	let feefrm = {};
	feefrm["document"] =  getStore(frmNm)?.id;
	feefrm["account"] = commisiAcc?.account;
	feefrm["subAccount"] = commisiAcc?.subAccount;
	feefrm["type"] ="debit";
	feefrm["amount"] = getStore(frmNm)?.paymentDepositFee*-1;
	feefrm["operationId"] = gen16CodeId();
	comp2save.push(feefrm)


	
	let feefrm2 = {};
	feefrm2["document"] =  getStore(frmNm)?.id;
	feefrm2["account"] = bankGlobal?.account;
	feefrm2["subAccount"] = bankGlobal?.subAccount;
	feefrm2["type"] ="credit";
	feefrm2["amount"] = getStore(frmNm)?.paymentDepositFee*-1;
	feefrm2["operationId"] = gen16CodeId();
	comp2save.push(feefrm2)

	*/

	getStore(frmNm)?.transactions?.map(trItm=>{
		const refNum = trItm.processorTransactionReference;

		let nnsTR = getStore(refNum)
		let amounTr =  trItm?.amount *1;
		let nnfrm = {};
		nnfrm["document"] =  trItm?.referenceNumber;
		nnfrm["account"] = nnsTR?.account;
		nnfrm["subAccount"] = nnsTR?.subAccount;
		nnfrm["type"] ="credit";
		nnfrm["amount"] = amounTr*1;
		nnfrm["operationId"] = gen16CodeId();
		comp2save.push(nnfrm)
	})


    let commonflds = {
        date: ffm.date,
        comprobanteId: comprobanteId,
        description: `Quickbook Deposit ID ${getStore(frmNm)?.id}`,
		businessId:  getStore("profileUser")?.businessId,
		year: (new Date(ffm["date"])).getFullYear()
    }

	delete ffm.date;

	
	
	
	let bdyq2 = {...getStore(qryStore())?.add_multi_opera};
	bdyq2.params = commonflds;
	bdyq2.form=comp2save;

	const res = fetchEncryptStream(bdyq2);
	const td = await res;
	if (td) {
		setTimeout(() => {
			updStore(multi_deposit_by_doc, null);
			
			updItm(getStore(frmNm)?.depositSummaryId,comprobanteId)
			
			getStore(frmNm)?.transactions?.map(trItm=>{
				const refNum = trItm.processorTransactionReference;
				updStore(refNum,null)
			})
			updStore("multi_deposit_anticipo_by_doc", null);
			updStore(frmNm, null);
			data?.modalID && CloseModal({id:data?.modalID});
			navigate({
				pathname: "/accounting-ledger" ,
				search: `?cId=${comprobanteId}`
			});
		}, 400);
	}
	else{

	}
	
	
	/*

	
	
	
	 */

};




const updItm = async (depositSummaryId,comprobanteId)=>{
	
	let bdyq2 = {...getStore(qryStore())?.upd_deposit_summary};
	bdyq2.params = {
		businessId: getStore("profileUser")?.businessId,
		depositSummaryId: depositSummaryId
	}
	bdyq2.data2update = {comprobanteId };
	const res = fetchEncryptStream(bdyq2);
	const td = await res;
	if (td && !td.error) {
		updStore("comprobanteIId","")
	}
}
	

	


const linkComprobante = ()=>{

	updItm(getStore(frmNm)?.depositSummaryId,getStore("comprobanteIId"))
}

	let bankGlobalAcc = getStore("global_account_params")?.cash_bank;
	let bankComisionsAcc = getStore("global_account_params")?.bankComisions;
	
	let linkComV = false;

	return (
		
		<div style={{
			maxHeight: "90vh",
			minHeight:  "88vh",
			width: "840px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
					Registrando Deposito
				</p>
				<div className="flexSpace"/>
				
			</div>
			{linkComV?
			<div className="_dsplFlx "  style={{margin: "18px 10px"}}>
						
				<div className="flexSpace"/>
				<TextInput  
					init={getStore("comprobanteIId")} 
					label={"comprobanteIId"} 
					width={120} 
					updChanges={(e)=>updStore("comprobanteIId",e)}
				/>
				<GrayButton  color={"#feb200"} label={"Link"}  clickHandler={linkComprobante}/>
				
				<div className="flexSpace"/>
				
			</div>
			:null}

			<div className="_dsplFlx"  style={{marginTop:25}}>
				<div className="flexSpace"/>
				{ bankGlobalAcc?.account?
					<div className=" acc_dtls">			
						<div className="_dsplFlx"  >
							<div className="code" style={{color: "#646cff"}} >
								{getStore("account_ids")?.[bankGlobalAcc?.account]?.code} 
							</div>
							<div className="name">
							{getStore("account_ids")?.[bankGlobalAcc?.account]?.name}
							</div>
						</div>
						<div className="flexSpace"/>
					</div>
					:null
				}
			</div>
				

			<div className="_dsplFlx ">
				
				
				<div className="flexSpace"/>
				<div className="_dsplFlx align_itm">
					<p className="key_docL">Documento:</p>
					<p className="value_docL">{getStore(frmNm)?.["id"]}</p>
				</div>
				<div className="_dsplFlx align_itm" style={{paddingLeft: 8}}>
					<p className="amount_docL">{"$"+getStore(frmNm)?.["amount"]}</p>
				</div>
				
			</div>



			<div className="_dsplFlx ">
				<p className="key_docL">Fecha:</p>
				<p className="value_docL">{parseDateMMDDYYYY(getStore(frmNm)?.["depositDate"])}</p>
			</div>
			<div className="value_docL" style={{textAlign:"left"}}>
			{`Quickbook Deposit ID ${getStore(frmNm)?.id}`}
			</div>
				<div className="separator" />

			{getStore(frmNm)?.transactions?.map(trItm=>{

				return (
					<TransitionItm data={trItm} key={trItm.id}  updObs={cb_result}/>
				)
			})}
						

			{
				SumCollects(getStore(frmNm)?.transactions)===0?
				<div className="_dsplFlx ">
					<div className="flexSpace"/>
				
					<div className="card">
						<button onClick={saveMulti}>
							Guardar
						</button>
					</div>
				</div>
			:null}

			
		</div>
	);
};

export default DepositManual;








const TransitionItm = ({
	
	data,
	updObs
}) => {


	const [obs, set_obs] = useState(0);

	const refNum = data.processorTransactionReference;

	

	

	const editSearchAccount = () => {
		updStore(refNum, null);
		updObs()
	}

	const handleSearchAccount = (acc) => {

		let nn= {
			"account":acc.account,
			"subAccount":acc.subAccount
		}
		updStore(refNum, nn);
		updObs()
	}



	let accountD = getStore("account_ids")?.[getStore(refNum)?.account];
	let subaccountD = getStore("sub_account_ids")?.[getStore(refNum)?.subAccount];
	let amount = ( data?.amount *1 + data?.totalTransactionFee*1).toFixed(2);
	let cleanName = data?.contactName?.split('/\n')?.join("");


	return (
		<div className=" ">
			<div className="_dsplFlx ">
			
			{accountD?.code ? 
			<div className="_dsplFlx ">
				<div className="_dsplFlx"  >
					{ accountD?.code?
						<div className=" acc_dtls">			
							<div className="_dsplFlx"  >
								<div className="code" style={{color: "#646cff"}} >
									{accountD?.code} 
								</div>
								<div className="name">
								{accountD?.name}
								</div>
							</div>
							<div className="flexSpace"/>
						</div>
						:null
					}
					{subaccountD ?
						<div className="_dsplFlx"  >
							<div className="code" style={{color: "#646cff"}} >
								{subaccountD?.code} 
							</div>
							<div className="name">
							{subaccountD?.name}
							</div>
						</div>
					:null}
				</div>
					<div className="flexSpace"/>
					<div className="icon" onClick={editSearchAccount}>
						<Svg name={"outline_edit"} color={"#1a73e8"}/>
					</div>
					</div>
				:
				<div className="_dsplFlx ">
					<div className="_dsplFlx align_itm" style={{marginRight: 40}}>
						<p className="key_docL">Name:</p>
						<p className="value_docL">{cleanName}</p>
					</div>
					<div className="flexSpace"/>
					<DropInput 
						placeholder={"buscar una cuenta"} 
						width={420}
						handleClick={handleSearchAccount}
					/>
				</div>
				}
				</div>
				<div className="_dsplFlx ">
					
					
					<div className="_dsplFlx align_itm">
						<p className="key_docL">Documento:</p>
						<p className="value_docL">{data?.referenceNumber}</p>
					</div>
					<div className="_dsplFlx align_itm" style={{paddingLeft: 8}}>
						<p className="amount_docL">{"$"+amount}</p>
					</div>
					<div className="flexSpace"/>
				</div>	

			</div>
		)
}

































const SumCollects = (trans) => {

	let balance = 0;
	trans && trans?.map((trItm, indE)=>{
		const refNum = trItm.processorTransactionReference;
		balance += getStore(refNum)?.account?0:1;
	});
	return  balance;
}  




